using UnityEngine;
using UnityEngine.UI;

namespace RacingPrototype
{
    /// <summary>
    /// Helpers for building thegameio-styled uGUI hierarchies from code (menus, HUD, results,
    /// world labels). Colours and font come from <see cref="BrandConfig"/>; UI sprites are loaded
    /// from Resources/UI (generated by the builder).
    /// </summary>
    public static class UIFactory
    {
        static Font builtinFont;
        public static Font DefaultFont
        {
            get
            {
                var brandFont = BrandConfig.Current.font;
                if (brandFont != null) return brandFont;
                return builtinFont != null ? builtinFont : (builtinFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"));
            }
        }

        public static BrandConfig Brand => BrandConfig.Current;
        public static Color PanelColour => WithAlpha(Brand.panel, 0.92f);
        public static Color Accent => Brand.primary;
        public static Color TextColour => Brand.text;
        public static Color MutedText => Brand.mutedText;

        public static Color WithAlpha(Color c, float a) { c.a = a; return c; }

        static Sprite rounded, circle, trophy;
        public static Sprite Rounded => rounded != null ? rounded : (rounded = Resources.Load<Sprite>("UI/RoundedPanel"));
        public static Sprite Circle => circle != null ? circle : (circle = Resources.Load<Sprite>("UI/Circle"));
        public static Sprite Trophy => trophy != null ? trophy : (trophy = Resources.Load<Sprite>("UI/Trophy"));

        public static RectTransform Rect(string name, Transform parent)
        {
            var go = new GameObject(name, typeof(RectTransform));
            go.layer = parent != null ? parent.gameObject.layer : 5;
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            return rt;
        }

        /// <summary>Anchors a rect to a single point of its parent.</summary>
        public static RectTransform Place(this RectTransform rt, Vector2 anchor, Vector2 pivot, Vector2 position, Vector2 size)
        {
            rt.anchorMin = anchor;
            rt.anchorMax = anchor;
            rt.pivot = pivot;
            rt.anchoredPosition = position;
            rt.sizeDelta = size;
            return rt;
        }

        /// <summary>Top-left placement helper (y grows downwards as a positive number).</summary>
        public static RectTransform TopLeft(this RectTransform rt, float x, float y, float w, float h) =>
            rt.Place(new Vector2(0, 1), new Vector2(0, 1), new Vector2(x, -y), new Vector2(w, h));

        public static RectTransform Stretch(this RectTransform rt, float left = 0f, float right = 0f, float top = 0f, float bottom = 0f)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.offsetMin = new Vector2(left, bottom);
            rt.offsetMax = new Vector2(-right, -top);
            return rt;
        }

        public static Image Panel(string name, Transform parent, Color colour, Sprite sprite = null)
        {
            var rt = Rect(name, parent);
            var img = rt.gameObject.AddComponent<Image>();
            img.color = colour;
            img.raycastTarget = false;
            if (sprite != null)
            {
                img.sprite = sprite;
                img.type = sprite.border.sqrMagnitude > 0f ? Image.Type.Sliced : Image.Type.Simple;
            }
            return img;
        }

        public static Image Card(string name, Transform parent, Color colour) => Panel(name, parent, colour, Rounded);

        public static Text Label(string name, Transform parent, string text, int size, TextAnchor anchor, Color colour,
            FontStyle style = FontStyle.Normal, bool shadow = false)
        {
            var rt = Rect(name, parent);
            var t = rt.gameObject.AddComponent<Text>();
            t.font = DefaultFont;
            t.text = text;
            t.fontSize = size;
            t.fontStyle = style;
            t.alignment = anchor;
            t.color = colour;
            t.supportRichText = true;
            t.horizontalOverflow = HorizontalWrapMode.Overflow;
            t.verticalOverflow = VerticalWrapMode.Overflow;
            t.raycastTarget = false;
            if (shadow)
            {
                var s = rt.gameObject.AddComponent<Shadow>();
                s.effectColor = new Color(0f, 0f, 0f, 0.6f);
                s.effectDistance = new Vector2(2f, -2f);
            }
            return t;
        }

        /// <summary>Multi-line wrapping label.</summary>
        public static Text Paragraph(string name, Transform parent, string text, int size, Color colour)
        {
            var t = Label(name, parent, text, size, TextAnchor.UpperLeft, colour);
            t.horizontalOverflow = HorizontalWrapMode.Wrap;
            t.verticalOverflow = VerticalWrapMode.Truncate;
            t.lineSpacing = 1.1f;
            return t;
        }

        public enum ButtonStyle { Primary, Secondary, Danger, Ghost }

        public static Button Button(string name, Transform parent, string label, int fontSize, ButtonStyle style = ButtonStyle.Secondary)
        {
            Color bg, fg;
            switch (style)
            {
                case ButtonStyle.Primary: bg = Brand.primary; fg = Brand.background; break;
                case ButtonStyle.Danger: bg = Brand.accentRed; fg = Color.white; break;
                case ButtonStyle.Ghost: bg = WithAlpha(Color.white, 0.06f); fg = Brand.text; break;
                default: bg = Brand.panelLight; fg = Brand.text; break;
            }
            return Button(name, parent, label, fontSize, bg, fg);
        }

        public static Button Button(string name, Transform parent, string label, int fontSize, Color background, Color textColour)
        {
            var img = Card(name, parent, background);
            img.raycastTarget = true;
            var button = img.gameObject.AddComponent<Button>();
            button.targetGraphic = img;
            button.navigation = new Navigation { mode = Navigation.Mode.None };
            var colours = button.colors;
            colours.normalColor = Color.white;
            colours.highlightedColor = new Color(1.18f, 1.18f, 1.18f, 1f);
            colours.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);
            colours.selectedColor = Color.white;
            colours.disabledColor = new Color(0.55f, 0.55f, 0.55f, 0.6f);
            colours.colorMultiplier = 1f;
            colours.fadeDuration = 0.08f;
            button.colors = colours;
            var text = Label("Label", img.transform, label, fontSize, TextAnchor.MiddleCenter, textColour, FontStyle.Bold);
            text.rectTransform.Stretch(12f, 12f, 0f, 0f);
            return button;
        }

        public static Text ButtonText(Button b) => b.GetComponentInChildren<Text>();

        /// <summary>thegameio wordmark, or the client logo sprite when one is assigned in BrandConfig.</summary>
        public static Graphic Wordmark(Transform parent, int size)
        {
            var brand = Brand;
            if (brand.logo != null)
            {
                var img = Panel("Logo", parent, Color.white, brand.logo);
                img.preserveAspect = true;
                return img;
            }
            var t = Label("Wordmark", parent, brand.wordmark, size, TextAnchor.MiddleCenter, brand.primary, FontStyle.Bold);
            return t;
        }

        /// <summary>Pill badge, e.g. pool status "Open" / "Full" / "Racing".</summary>
        public static Text Badge(string name, Transform parent, string text, Color colour, int fontSize, out Image background)
        {
            background = Card(name, parent, colour);
            var t = Label("Text", background.transform, text, fontSize, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            t.rectTransform.Stretch(6, 6, 0, 0);
            return t;
        }

        /// <summary>Five-segment stat bar in the PPT style (red squares).</summary>
        public static Image[] StatBar(Transform parent, float x, float y, float segment = 22f, float gap = 6f, float height = 14f)
        {
            var cells = new Image[5];
            for (int i = 0; i < 5; i++)
            {
                cells[i] = Panel("Seg " + (i + 1), parent, Brand.accentRed);
                cells[i].rectTransform.TopLeft(x + i * (segment + gap), y, segment, height);
            }
            return cells;
        }

        public static void SetStatBar(Image[] cells, int value)
        {
            if (cells == null) return;
            for (int i = 0; i < cells.Length; i++)
                cells[i].color = i < value ? Brand.accentRed : WithAlpha(Color.white, 0.14f);
        }

        public static InputField TextInput(string name, Transform parent, string value, string placeholder, int fontSize)
        {
            var bg = Card(name, parent, Brand.panelLight);
            bg.raycastTarget = true;
            var field = bg.gameObject.AddComponent<InputField>();
            var text = Label("Text", bg.transform, value, fontSize, TextAnchor.MiddleLeft, Brand.text);
            text.supportRichText = false;
            text.rectTransform.Stretch(14, 14, 0, 0);
            var ph = Label("Placeholder", bg.transform, placeholder, fontSize, TextAnchor.MiddleLeft, Brand.mutedText, FontStyle.Italic);
            ph.rectTransform.Stretch(14, 14, 0, 0);
            field.textComponent = text;
            field.placeholder = ph;
            field.targetGraphic = bg;
            field.text = value;
            field.navigation = new Navigation { mode = Navigation.Mode.None };
            return field;
        }

        public static Color TrophyColour(int rank) => rank == 1 ? Brand.gold : rank == 2 ? Brand.silver : Brand.bronze;

        /// <summary>Gold / silver / bronze trophy disc for ranks 1-3.</summary>
        public static Image TrophyDisc(Transform parent, int rank, float size)
        {
            var disc = Panel("Trophy " + rank, parent, TrophyColour(rank), Circle);
            disc.rectTransform.sizeDelta = new Vector2(size, size);
            var cup = Panel("Cup", disc.transform, Color.white, Trophy);
            cup.rectTransform.Stretch(size * 0.2f, size * 0.2f, size * 0.18f, size * 0.22f);
            cup.preserveAspect = true;
            return disc;
        }

        /// <summary>
        /// World-space text (number plates, gantry, billboards). Readable by a viewer looking along
        /// the transform's forward axis.
        /// </summary>
        public static Text WorldText(string name, Transform parent, string text, Vector3 localPosition, Quaternion localRotation,
            Vector2 sizeMetres, Color colour, FontStyle style = FontStyle.Bold, int maxFontSize = 160)
        {
            // Keep glyphs at <= ~140 px so large signs never overflow the dynamic font atlas
            // (oversized text silently disappears): big signs use fewer canvas units per metre.
            maxFontSize = Mathf.Min(maxFontSize, 140);
            float unitsPerMetre = Mathf.Clamp(150f / Mathf.Max(sizeMetres.y, 0.01f), 15f, 200f);
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.localPosition = localPosition;
            rt.localRotation = localRotation;
            rt.localScale = Vector3.one / unitsPerMetre;
            rt.sizeDelta = sizeMetres * unitsPerMetre;

            var canvas = go.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            var scaler = go.AddComponent<CanvasScaler>();
            scaler.dynamicPixelsPerUnit = unitsPerMetre >= 150f ? 2f : 1.5f;

            var label = Label("Text", rt, text, maxFontSize, TextAnchor.MiddleCenter, colour, style);
            label.rectTransform.Stretch();
            label.resizeTextForBestFit = true;
            label.resizeTextMinSize = 8;
            label.resizeTextMaxSize = maxFontSize;
            label.horizontalOverflow = HorizontalWrapMode.Wrap;
            label.verticalOverflow = VerticalWrapMode.Truncate;
            return label;
        }
    }
}
